<?php
 require_once(__DIR__ . '/../../init.php'); class med_ambulance_linkCall { const TASK_NAME = 'medAmbulanceLinkCall'; const DEBUG_HTTP = true; private $db; private $extraSettings; public function startExchange($params = null) { $privateKey = file_get_contents(__DIR__ . '/../../../../../crt/private.pem'); suspendJsonRpc(); require_once(__DIR__ . '/../../../lib/php-jwt/JWT.php'); resumeJsonRpc(); $items = $this->getData($params); if ($items) { $JWTService = new Firebase\JWT\JWT(); $arr = []; $arr[0] = json_encode($items, JSON_UNESCAPED_UNICODE); $data = $JWTService->encode($arr, $privateKey, 'RS256'); if ($this->sendData($data)) { $this->updateData($items); } } else { return true; } } private function getData($params = null) { $db = $this->db ?: $this->db = connectDb(); $sql = <<<"EOT"
