return selectSql($db, $sql); } private function sendData($data) { $params = $this->setupConnect(); $params->request_content = $data; $result = httpPOST($params); if ($result) { switch ($result['status'][1]) { case "200": $this->log("Сихронизация завершена"); break; case "404": case "400": $this->log("Ошибка", 2); break; default: $this->log("Что-то пошло не так...", 2); break; } return true; } else { $this->log("Ошибка подключения к ЦОД"); return false; } } private function updateData($records) { $db = $this->db ?: $this->db = connectDb(); $sql = <<<"EOT"
