    linkstatus = null
where medemergencycode = ?
EOT;
$stmt = $db->prepare($sql); if (is_object($records)) { $records = [$records]; } $db->beginTransaction(); try { foreach ($records as $row) { $stmt->execute([ $row['medemergencycode'] ]); } $db->commit(); } catch (Throwable $e) { $db->rollback(); throw $e; } return true; } private function setupConnect(): stdClass { $settings = $this->getSettings(); if (!httpCreateParam($settings)) { $message = "Ошибка инициализация подключюения"; $this->log($message, 1); throw new Exception($message); } $params = new stdClass(); $params->url = $settings->url; $params->proxy = $this->getProxySettings($settings); $params->headers['Content-Type'] = "application/json"; $params->debug = self::DEBUG_HTTP; return $params; } private function getSettings() { if (!empty($this->extraSettings)) { return $this->extraSettings; } $this->log('Загрузка настроек...'); $settings = readExtraSettings($this->db, self::TASK_NAME); return $this->checkSettings($settings); } private function checkSettings($settings) { $settingsValid = true; if (empty($settings)) { $this->log('Не произведена настройка обмена информацией с ЦРБ', 2); } elseif (isset($settings->active) && $settings->active) { if (empty($settings->url)) { $this->log('Не заполнена настройка Адрес сервера', 2); $settingsValid = false; } if ($settingsValid) { $settings->task = self::TASK_NAME; $this->log('Настройки загружены успешно'); $this->extraSettings = $settings; $result = $this->extraSettings; } else { throw new Exception('Проверьте правильность заполнения данных для подключения.'); } } else { $this->log('В настройках запрещен обмен данными', 1); throw new Exception('В настройках запрещен обмен данными'); } return $result; } private function getProxySettings($settings) { return $settings->proxyUse ? array( 'host' => isEmptyProperty($settings, 'proxyServer', ''), 'port' => isEmptyProperty($settings, 'proxyPort', 0), 'usr' => isEmptyProperty($settings, 'proxyUser', ''), 'pwd' => isEmptyProperty($settings, 'proxyPassword', '') ) : array(); } private function log($message, $type = 0) { app_log($message, $type, self::TASK_NAME); } } $service = new med_ambulance_linkCall(); $service->startExchange(); 